{
  "schemaVersion": "0.2",
  "id": "sales",
  "mode": "intent",
  "data": {
    "kind": "inline",
    "fields": ["month", "revenue"],
    "rows": [
      {
        "month": "Jan",
        "revenue": 120
      },
      {
        "month": "Feb",
        "revenue": 180
      },
      {
        "month": "Mar",
        "revenue": 150
      }
    ]
  },
  "chart": {
    "type": "bar",
    "title": "Monthly sales",
    "encoding": {
      "x": {
        "field": "month",
        "type": "ordinal"
      },
      "y": {
        "field": "revenue",
        "type": "quantitative"
      }
    }
  },
  "presentation": {
    "detailLevel": "minimal"
  }
}

{
  "schemaVersion": "0.2",
  "id": "orders",
  "mode": "intent",
  "data": {
    "kind": "inline",
    "fields": ["day", "region", "orders"],
    "rows": [
      {
        "day": "Mon",
        "region": "East",
        "orders": 4
      },
      {
        "day": "Tue",
        "region": "West",
        "orders": null
      },
      {
        "day": "Tue",
        "region": "East",
        "orders": 0
      },
      {
        "day": "Mon",
        "region": "West",
        "orders": 10
      }
    ]
  },
  "chart": {
    "type": "heatmap",
    "title": "Orders",
    "encoding": {
      "x": {
        "field": "day",
        "type": "ordinal"
      },
      "y": {
        "field": "region",
        "type": "ordinal"
      }
    },
    "heatmap": {
      "field": "orders",
      "min": 0,
      "max": 10
    }
  }
}

{
  "schemaVersion": "0.2",
  "id": "sales",
  "mode": "intent",
  "data": {
    "kind": "inline",
    "fields": ["month", "sales", "cost"],
    "rows": [
      {
        "month": "Jan",
        "sales": 120,
        "cost": 90
      },
      {
        "month": "Feb",
        "sales": 180,
        "cost": 130
      },
      {
        "month": "Mar",
        "sales": 150,
        "cost": 110
      }
    ]
  },
  "chart": {
    "type": "combo",
    "title": "Sales and cost",
    "encoding": {
      "x": {
        "field": "month",
        "type": "ordinal"
      },
      "y": {
        "field": "sales",
        "type": "quantitative",
        "unit": {
          "kind": "currency",
          "code": "USD"
        }
      }
    },
    "secondary": {
      "field": "cost",
      "unit": {
        "kind": "currency",
        "code": "USD"
      }
    }
  },
  "presentation": {
    "legend": {
      "show": true
    }
  }
}

{
  "schemaVersion": "0.2",
  "id": "funnel",
  "mode": "intent",
  "data": {
    "kind": "inline",
    "fields": ["stage", "users"],
    "rows": [
      {
        "stage": "Visit",
        "users": 1000
      },
      {
        "stage": "Sign up",
        "users": 350
      },
      {
        "stage": "Purchase",
        "users": 90
      }
    ]
  },
  "chart": {
    "type": "funnel",
    "title": "Conversion stages",
    "encoding": {
      "x": {
        "field": "stage",
        "type": "ordinal"
      },
      "y": {
        "field": "users",
        "type": "quantitative"
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://chartnexus.dev/schemas/native-strict-basic/0.1",
  "title": "NativeStrictBasicOption",
  "description": "Experimental bounded subset of ECharts option, not the full ECharts schema.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "title": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "text": {
          "type": "string",
          "maxLength": 256
        }
      }
    },
    "legend": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "show": {
          "type": "boolean"
        }
      }
    },
    "xAxis": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": ["category", "value"]
        },
        "name": {
          "type": "string",
          "maxLength": 256
        },
        "data": {
          "type": "array",
          "maxItems": 10000,
          "items": {
            "type": "string",
            "maxLength": 256
          }
        }
      },
      "required": ["type"]
    },
    "yAxis": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": ["category", "value"]
        },
        "name": {
          "type": "string",
          "maxLength": 256
        },
        "data": {
          "type": "array",
          "maxItems": 10000,
          "items": {
            "type": "string",
            "maxLength": 256
          }
        }
      },
      "required": ["type"]
    },
    "series": {
      "type": "array",
      "minItems": 1,
      "maxItems": 50,
      "items": {
        "oneOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 256
              },
              "id": {
                "type": "string",
                "maxLength": 256
              },
              "type": {
                "enum": ["bar", "line"]
              },
              "stack": {
                "type": "string",
                "maxLength": 256
              },
              "data": {
                "type": "array",
                "maxItems": 10000,
                "items": {
                  "type": ["number", "null"]
                }
              }
            },
            "required": ["type", "data"]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 256
              },
              "id": {
                "type": "string",
                "maxLength": 256
              },
              "type": {
                "const": "scatter"
              },
              "data": {
                "type": "array",
                "maxItems": 10000,
                "items": {
                  "type": "array",
                  "prefixItems": [
                    {
                      "type": "number"
                    },
                    {
                      "type": ["number", "null"]
                    }
                  ],
                  "items": false,
                  "minItems": 2,
                  "maxItems": 2
                }
              }
            },
            "required": ["type", "data"]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 256
              },
              "id": {
                "type": "string",
                "maxLength": 256
              },
              "type": {
                "const": "pie"
              },
              "data": {
                "type": "array",
                "maxItems": 10000,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "name": {
                      "type": "string",
                      "maxLength": 256
                    },
                    "value": {
                      "type": "number",
                      "minimum": 0
                    }
                  },
                  "required": ["name", "value"]
                }
              }
            },
            "required": ["type", "data"]
          }
        ]
      }
    },
    "tooltip": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "show": {
          "type": "boolean"
        }
      }
    },
    "color": {
      "type": "array",
      "minItems": 1,
      "maxItems": 50,
      "items": {
        "type": "string",
        "pattern": "^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$"
      }
    },
    "backgroundColor": {
      "type": "string",
      "pattern": "^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$"
    }
  },
  "required": ["series"]
}

{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "const": "0.2"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "maxLength": 256
    },
    "mode": {
      "const": "intent"
    },
    "data": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "kind": {
              "const": "inline"
            },
            "fields": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "uniqueItems": true,
              "minItems": 1,
              "maxItems": 100
            },
            "rows": {
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": {
                  "anyOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "number"
                    },
                    {
                      "type": "boolean"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "maxProperties": 100
              },
              "maxItems": 10000
            }
          },
          "required": ["kind", "fields", "rows"]
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "kind": {
              "const": "reference"
            },
            "id": {
              "type": "string",
              "minLength": 1,
              "maxLength": 256
            },
            "revision": {
              "type": "string",
              "minLength": 1,
              "maxLength": 256
            }
          },
          "required": ["kind", "id", "revision"]
        }
      ]
    },
    "chart": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": [
            "bar",
            "line",
            "pie",
            "scatter",
            "combo",
            "funnel",
            "heatmap"
          ]
        },
        "encoding": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "x": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "field": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 128
                },
                "type": {
                  "enum": ["ordinal", "quantitative", "temporal"]
                },
                "temporalKind": {
                  "enum": ["date", "instant"]
                }
              },
              "required": ["field", "type"]
            },
            "y": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "field": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 128
                },
                "type": {
                  "enum": ["ordinal", "quantitative"]
                },
                "unit": {
                  "oneOf": [
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "kind": {
                          "const": "currency"
                        },
                        "code": {
                          "type": "string",
                          "pattern": "^[A-Z]{3}$"
                        }
                      },
                      "required": ["kind", "code"]
                    },
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "kind": {
                          "const": "percent"
                        },
                        "scale": {
                          "enum": ["percent", "ratio"]
                        }
                      },
                      "required": ["kind", "scale"]
                    },
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "kind": {
                          "const": "unit"
                        },
                        "label": {
                          "type": "string",
                          "minLength": 1,
                          "maxLength": 32
                        }
                      },
                      "required": ["kind", "label"]
                    }
                  ]
                }
              },
              "required": ["field", "type"]
            },
            "series": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "field": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 128
                }
              },
              "required": ["field"]
            }
          },
          "required": ["x", "y"]
        },
        "stack": {
          "type": "boolean"
        },
        "title": {
          "type": "string",
          "maxLength": 256
        },
        "orientation": {
          "enum": ["vertical", "horizontal"]
        },
        "area": {
          "type": "boolean"
        },
        "donut": {
          "type": "boolean"
        },
        "sort": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "by": {
              "enum": ["category", "value"]
            },
            "order": {
              "enum": ["ascending", "descending"]
            },
            "nulls": {
              "enum": ["first", "last"]
            }
          },
          "required": ["by", "order", "nulls"]
        },
        "aggregate": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "op": {
              "enum": ["sum", "mean", "count"]
            }
          },
          "required": ["op"]
        },
        "secondary": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "field": {
              "type": "string",
              "minLength": 1,
              "maxLength": 128
            },
            "unit": {
              "oneOf": [
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "const": "currency"
                    },
                    "code": {
                      "type": "string",
                      "pattern": "^[A-Z]{3}$"
                    }
                  },
                  "required": ["kind", "code"]
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "const": "percent"
                    },
                    "scale": {
                      "enum": ["percent", "ratio"]
                    }
                  },
                  "required": ["kind", "scale"]
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "const": "unit"
                    },
                    "label": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 32
                    }
                  },
                  "required": ["kind", "label"]
                }
              ]
            },
            "axis": {
              "enum": ["shared", "right"]
            }
          },
          "required": ["field"]
        },
        "heatmap": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "field": {
              "type": "string",
              "minLength": 1,
              "maxLength": 128
            },
            "min": {
              "type": "number"
            },
            "max": {
              "type": "number"
            }
          },
          "required": ["field", "min", "max"]
        }
      },
      "required": ["type", "encoding"]
    },
    "presentation": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "theme": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "id": {
              "enum": ["light", "dark"]
            },
            "version": {
              "const": "1",
              "type": "string"
            }
          },
          "required": ["id", "version"]
        },
        "dataLabels": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "show": {
              "type": "boolean"
            }
          },
          "required": ["show"]
        },
        "legend": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "show": {
              "type": "boolean"
            },
            "position": {
              "enum": ["top", "bottom"]
            }
          },
          "required": ["show"]
        },
        "detailLevel": {
          "enum": [
            "minimal",
            "simple",
            "standard",
            "detailed",
            "comprehensive"
          ],
          "description": "Display intent applied only when the host opts into the chat presentation profile; host policy may override it."
        }
      }
    }
  },
  "required": ["schemaVersion", "id", "mode", "data", "chart"],
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://chartnexus.dev/schemas/chart-document/0.2",
  "title": "ChartDocument02",
  "description": "Experimental ChartNexus 0.2 intent profile; no network resolution."
}

{
  "id": "basic-0.2",
  "schemaVersion": "0.2",
  "status": "experimental",
  "charts": ["bar", "line", "pie", "scatter", "combo", "funnel", "heatmap"],
  "modes": ["intent"],
  "variants": {
    "bar": ["horizontal"],
    "line": ["area"],
    "pie": ["donut"]
  },
  "themes": [
    {
      "id": "light",
      "version": "1"
    },
    {
      "id": "dark",
      "version": "1"
    }
  ],
  "outputs": ["browser", "svg"],
  "limits": {
    "bytes": 1048576,
    "depth": 32,
    "rows": 10000,
    "series": 50,
    "points": 50000,
    "dimension": 4096
  },
  "sorting": {
    "charts": ["bar", "line", "pie", "funnel"],
    "by": ["category", "value"],
    "orders": ["ascending", "descending"],
    "nulls": ["first", "last"],
    "groupedValue": "unsupported",
    "collation": "utf16-code-unit"
  },
  "units": {
    "charts": ["bar", "line", "scatter"],
    "kinds": ["currency", "percent", "unit"],
    "percentScales": ["percent", "ratio"],
    "conversion": false
  },
  "temporal": {
    "charts": ["line"],
    "kinds": ["date", "instant"],
    "dateFormat": "YYYY-MM-DD",
    "instantFormat": "YYYY-MM-DDTHH:mm:ss[.SSS]Z or ±HH:mm",
    "years": "1000-9999",
    "coordinate": "UTC",
    "displayTimezone": "UTC",
    "namedTimezones": false,
    "numericTimestamps": false
  },
  "aggregation": {
    "charts": ["bar", "line", "pie", "funnel"],
    "operations": ["sum", "mean", "count"],
    "count": "non-null numeric y",
    "allNull": {
      "sum": "null",
      "mean": "null",
      "count": 0
    },
    "identity": "aggregate"
  },
  "presentation": {
    "dataLabels": {
      "show": true,
      "content": "echarts-default",
      "formatter": false
    },
    "legend": {
      "show": true,
      "positions": ["top", "bottom"]
    }
  },
  "combo": {
    "series": ["bar", "line"],
    "axes": ["shared", "right"],
    "x": "ordinal",
    "grouping": false,
    "aggregation": false,
    "units": "shared requires identical or both absent; right requires explicit units for both"
  },
  "funnel": {
    "x": "ordinal",
    "y": "nonnegative",
    "order": "input unless explicitly sorted",
    "conversionRate": "not inferred"
  },
  "heatmap": {
    "x": "ordinal",
    "y": "ordinal",
    "value": "quantitative",
    "range": "explicit",
    "missing": "null is not rendered",
    "duplicates": "rejected",
    "sorting": false,
    "aggregation": false
  },
  "chatPresentation": {
    "status": "experimental",
    "hostOptIn": true,
    "detailLevels": [
      "minimal",
      "simple",
      "standard",
      "detailed",
      "comprehensive"
    ],
    "themes": ["light", "dark"],
    "backgrounds": ["transparent", "theme"],
    "defaultLevel": "standard",
    "defaultTheme": "light",
    "defaultBackground": "transparent"
  }
}

